/* Primitive values are deduplicated from the normalized model. */
/* Semantic variables preserve token roles and evidence metadata. */
:root {
  --ds-color-primitive-1: rgb(51, 68, 136); /* role: Primary hyperlink color; status: detected; confidence: 1.00; source: web_1; value: rgb(51, 68, 136) */
  --ds-color-primitive-2: rgb(238, 238, 238); /* role: Page background; status: detected; confidence: 1.00; source: web_1; value: rgb(238, 238, 238) */
  --ds-color-primitive-3: rgb(0, 0, 0); /* role: Main body and heading text color; status: detected; confidence: 1.00; source: web_1; value: rgb(0, 0, 0) */
  --ds-font-family-primitive-1: system-ui, sans-serif; /* role: Body and layout font family; status: detected; confidence: 1.00; source: web_1; value: system-ui, sans-serif */
  --ds-font-family-primitive-2: "Times New Roman"; /* role: Fallback serif font family; status: detected; confidence: 1.00; source: web_1; value: "Times New Roman" */

  /* Semantic roles */
  --ds-color-brand-link-blue: var(--ds-color-primitive-1); /* role: Primary hyperlink color; status: detected; confidence: 1.00; source: web_1 */
  --ds-color-surface-page: var(--ds-color-primitive-2); /* role: Page background; status: detected; confidence: 1.00; source: web_1 */
  --ds-color-text-primary: var(--ds-color-primitive-3); /* role: Main body and heading text color; status: detected; confidence: 1.00; source: web_1 */
  --ds-font-family-font-family-body: var(--ds-font-family-primitive-1); /* role: Body and layout font family; status: detected; confidence: 1.00; source: web_1 */
  --ds-font-family-font-family-serif: var(--ds-font-family-primitive-2); /* role: Fallback serif font family; status: detected; confidence: 1.00; source: web_1 */
}

